function expandOptions(s: string): string[] {
  let words = [""];
  for (let i = 0; i < s.length; i++) {
    let opts: string[];
    if (s[i] === "{") {
      const j = s.indexOf("}", i);
      opts = s.slice(i + 1, j).split(",");
      i = j;
    } else opts = [s[i]];
    const next: string[] = [];
    for (const w of words) for (const c of opts) next.push(w + c);
    words = next;
  }
  return words.sort();
}

