function expandOptions(s: string): string[] {
  const slots: string[][] = [];
  for (let i = 0; i < s.length; i++) {
    if (s[i] === "{") {
      const j = s.indexOf("}", i);
      slots.push(s.slice(i + 1, j).split(",").sort());
      i = j;
    } else slots.push([s[i]]);
  }
  const out: string[] = [], word: string[] = [];
  const dfs = (i: number): void => {
    if (i === slots.length) { out.push(word.join("")); return; }
    for (const c of slots[i]) {
      word.push(c);
      dfs(i + 1);
      word.pop();
    }
  };
  dfs(0);
  return out;
}

