class Solution:
    def expandOptions(self, s: str) -> List[str]:
        slots, i = [], 0
        while i < len(s):
            if s[i] == "{":
                j = s.index("}", i)
                slots.append(sorted(s[i + 1:j].split(",")))
                i = j + 1
            else:
                slots.append([s[i]])
                i += 1
        out, word = [], []

        def dfs(k):
            if k == len(slots):
                out.append("".join(word))
                return
            for c in slots[k]:
                word.append(c)
                dfs(k + 1)
                word.pop()

        dfs(0)
        return out

